SELECT id, customer_id, customer_name, reminder_time, content, status, create_time, update_time
FROM customer_reminder
WHERE id = #{id} AND reminder_user_id = #{userId}

SELECT id, customer_id, customer_name, reminder_time, content, status, organization_id, reminder_user_id, create_user, update_user, create_time, update_time
FROM customer_reminder
WHERE reminder_time <= #{currentTime} AND status = 'PENDING' AND organization_id = #{orgId}
